import click
from click.testing import CliRunner

@click.command()
@click.option('-c', '--config', hidden=True, help='Config file.')
@click.option('-v', '--verbose', is_flag=True, help='Be loud.')
def cli(config, verbose): pass

ctx = click.Context(cli)
for p in cli.params:
    print(repr(p.name), '->', repr(p.get_help_spec(ctx)), '| record:', p.get_help_record(ctx))

print('---help output---')
print(CliRunner().invoke(cli, ['--help']).output)
